const crypto = require('crypto');

function hashPassword(password, salt) {
  return crypto.createHash('sha256').update(salt + password).digest('hex');
}

function generateSalt() {
  return crypto.randomBytes(16).toString('hex');
}

function generateToken() {
  return crypto.randomUUID();
}

function tokenExpires(hours = 24) {
  return new Date(Date.now() + hours * 3600000).toISOString();
}

function isExpired(isoDate) {
  if (!isoDate) return true;
  return new Date(isoDate) < new Date();
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidTime(time) {
  return /^([01]?\d|2[0-3]):[0-5]\d$/.test(time);
}

function isValidUsername(name) {
  return /^[a-zA-Z0-9_]{3,20}$/.test(name);
}

function isStrongPassword(pwd) {
  return pwd.length >= 8 && /[A-Za-z]/.test(pwd) && /\d/.test(pwd);
}


const trigger = $('When Executed by Another Workflow').first().json;
const action = trigger.action;
const token = trigger.sessionToken || '';
const rows = $input.all().map(i => i.json);
const user = rows.find(r => r.session_token === token);

if (!user || isExpired(user.session_expires_at)) {
  return { json: { success: false, error: 'Session invalide ou expirée.' } };
}

if (action === 'view') {
  return {
    json: {
      success: true,
      username: user.username,
      email: user.email,
      interests: user.interests,
      schedule_time: user.schedule_time,
      active: user.active !== false,
      blocked_topics: user.blocked_topics || '',
      blocked_sources: user.blocked_sources || '',
      preferences: user.preferences || '',
      newsletter_style: user.newsletter_style || 'standard'
    }
  };
}

const field = trigger.field;
const value = (trigger.value || '').trim();
const allowed = ['email', 'interests', 'schedule_time'];

if (!allowed.includes(field)) {
  return { json: { success: false, error: 'Champ non autorisé.' } };
}
if (field === 'email' && !isValidEmail(value)) {
  return { json: { success: false, error: 'Email invalide.' } };
}
if (field === 'schedule_time' && !isValidTime(value)) {
  return { json: { success: false, error: 'Horaire invalide.' } };
}
if (field === 'interests' && value.length < 2) {
  return { json: { success: false, error: 'Intérêts invalides.' } };
}

return {
  json: {
    _update: true,
    username: user.username,
    field,
    value,
    success: true,
    error: null
  }
};

const d = $json;
const out = { username: d.username, session_token: $('Get All Users').all().find(i => i.json.username === d.username)?.json?.session_token };
out[d.field] = d.value;
return { json: out };
